import{_ as t,c as o,o as l,ah as c}from"./chunks/framework.DE7iKuik.js";const P=JSON.parse('{"title":"HTTP请求方法说明","description":null,"frontmatter":{"title":"HTTP请求方法说明","createTime":"2024/02/01 15:52:44","permalink":"/article/http-method/","tags":[],"description":null,"lastUpdated":"2026-01-20","link":"/posts/http-method","layout":"doc","prev":{"text":"HTTP请求头和响应头信息","link":"/posts/http-header"},"next":{"text":"JavaScript特殊字符转义字符对照表","link":"/posts/javascript-special-characters"}},"headers":[],"params":{"pkg":"http-method"},"relativePath":"posts/http-method.md","filePath":"posts/[pkg].md"}'),i={name:"posts/http-method.md"};function d(p,e,a,T,s,r){return l(),o("div",null,[...e[0]||(e[0]=[c("<p>根据HTTP标准，HTTP请求可以使用多种请求方法。</p><ul><li><code>HEAD</code> 类似于get请求，只不过返回的响应中没有具体的内容，用于获取报头</li><li><code>POST</code> 向指定资源提交数据进行处理请求（例如提交表单或者上传文件）。数据被包含在请求体中。POST请求可能会导致新的资源的建立和/或已有资源的修改。</li><li><code>PUT</code> 从客户端向服务器传送的数据取代指定的文档的内容。</li><li><code>DELETE</code> 请求服务器删除指定的页面。</li><li><code>CONNECT</code> HTTP/1.1协议中预留给能够将连接改为管道方式的代理服务器。</li><li><code>OPTIONS</code> 允许客户端查看服务器的性能。</li><li><code>TRACE</code> 回显服务器收到的请求，主要用于测试或诊断。</li><li><code>PATCH</code> 实体中包含一个表，表中说明与该URI所表示的原内容的区别。</li><li><code>MOVE</code> 请求服务器将指定的页面移至另一个网络地址。</li><li><code>COPY</code> 请求服务器将指定的页面拷贝至另一个网络地址。</li><li><code>LINK</code> 请求服务器建立链接关系。</li><li><code>UNLINK</code> 断开链接关系。</li><li><code>WRAPPED</code> 允许客户端发送经过封装的请求。</li><li><code>Extension-mothed</code> 在不改动协议的前提下，可增加另外的方法。</li></ul><blockquote><p>HTTP1.0定义了三种请求方法： GET, POST 和 HEAD方法。</p></blockquote><blockquote><p>HTTP1.1新增了五种请求方法：OPTIONS, PUT, DELETE, TRACE 和 CONNECT 方法。</p></blockquote>",4)])])}const _=t(i,[["render",d]]);export{P as __pageData,_ as default};
